mapper.select:
select from asset_business_flow
project_id = #{projectId}
order by created_at desc

mapper.insert:
insert into asset_business_flow (
    id, project_id, code, name, description, flow_json, priority, status,
    lifecycle_status, archived_at, deleted_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{code},
    #{name}, #{description}, cast(coalesce(#{flowJson}, '{}') as jsonb),
    #{priority}, #{status}, #{lifecycleStatus}, #{archivedAt}, #{deletedAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
update asset_business_flow set
    lifecycle_status = #{lifecycleStatus},
    archived_at = #{archivedAt},
    deleted_at = #{deletedAt},
    updated_at = #{updatedAt}
where id = #{id}

mapper.select:
